package org.example.achat.procurement.api.dto;

import jakarta.validation.Valid;

import java.time.LocalDate;
import java.util.List;

/** Payload of {@code POST /cqrs/factures}; the invoice id is generated by the API. */
public record CqrsInvoiceRequest(
        float montantRemise,
        float montantFacture,
        LocalDate dateCreationFacture,
        LocalDate dateDerniereModificationFacture,
        Boolean archivee,
        Long fournisseurId,
        List<@Valid CqrsInvoiceLineRequest> lignes) {
}
